<script setup lang="ts">
type Contractor={id:number;name:string;logo:string;operationalArea:string;activity:string;subActivity:string;nace:string;dangerClass:string;sgk:string;status:"active"|"passive";contractorType:string}
const props=defineProps<{ contractors:Contractor[]; search?:string; statusFilter?:"all"|"active"|"passive" }>()
const filtered=computed(()=>{const t=(props.search||'').trim().toLocaleLowerCase('tr-TR');return props.contractors.filter(x=>(!t||`${x.name} ${x.activity} ${x.subActivity} ${x.nace} ${x.dangerClass} ${x.sgk} ${x.contractorType}`.toLocaleLowerCase('tr-TR').includes(t))&&(props.statusFilter==='all'||!props.statusFilter||x.status===props.statusFilter))})
</script>
<template><div class="overflow-hidden rounded-lg border border-gray-200 dark:border-gray-800"><table class="w-full text-left"><thead class="bg-gray-50"><tr><th class="px-4 py-3 text-xs text-gray-500">Taşeron</th><th class="px-4 py-3 text-xs text-gray-500">Faaliyet</th><th class="px-4 py-3 text-xs text-gray-500">Alt Faaliyet</th><th class="px-4 py-3 text-xs text-gray-500">Tip</th><th class="px-4 py-3 text-xs text-gray-500">Durum</th></tr></thead><tbody class="divide-y divide-gray-100"><tr v-for="x in filtered" :key="x.id"><td class="px-4 py-4 text-sm font-semibold">{{x.name}}</td><td class="px-4 py-4 text-sm">{{x.activity}}</td><td class="px-4 py-4 text-sm">{{x.subActivity}}</td><td class="px-4 py-4 text-sm">{{x.contractorType}}</td><td class="px-4 py-4 text-sm">{{x.status==='active'?'Aktif':'Pasif'}}</td></tr></tbody></table></div></template>